import java.util.*;

class Solution {
    public boolean canFinish(int n, int[][] needs) {
        List<List<Integer>> next = new ArrayList<>();
        for (int i = 0; i < n; i++) next.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] p : needs) { next.get(p[1]).add(p[0]); indeg[p[0]]++; } // b -> a
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) q.add(i);
        int done = 0;
        while (!q.isEmpty()) {
            int v = q.poll();
            done++;
            for (int u : next.get(v)) if (--indeg[u] == 0) q.add(u);
        }
        return done == n; // anything left is stuck in a cycle
    }
}

