class Solution:
    def canFinish(self, n: int, needs: List[List[int]]) -> bool:
        g = [[] for _ in range(n)]; deg = [0] * n
        for a, b in needs: g[b].append(a); deg[a] += 1
        q = deque(v for v in range(n) if deg[v] == 0); done = 0
        while q:
            v = q.popleft(); done += 1
            for u in g[v]:
                deg[u] -= 1
                if deg[u] == 0: q.append(u)
        return done == n

