function canFinish(n, needs) {
  const g = Array.from({length: n}, () => []), state = new Array(n).fill(0);
  for (const [a, b] of needs) g[b].push(a);
  for (let s = 0; s < n; s++) {
    if (state[s]) continue; const st = [[s, 0]]; state[s] = 1;
    while (st.length) { const top = st[st.length - 1], v = top[0];
      if (top[1] < g[v].length) { const u = g[v][top[1]++]; if (state[u] === 1) return false; if (!state[u]) { state[u] = 1; st.push([u, 0]); } }
      else { state[v] = 2; st.pop(); } }
  }
  return true;
}
